      "@type": "FAQPage",
      "@id": "https://www.data4thepeople.com/p/fuel-surcharge-impact-viz#faq",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What is a diesel fuel surcharge?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It is an extra charge on a freight bill that rises and falls with the price of diesel. Most carriers tie it to EIA's weekly national average price. Truckload surcharges are usually charged per mile; LTL and rail surcharges are usually a percentage of the base charge."
          }
        },
        {
          "@type": "Question",
          "name": "How is a truckload fuel surcharge calculated?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A common formula is the EIA diesel price minus a base price, often $1.25, divided by an assumed fuel economy, often 6 miles per gallon. At $6.529 that is 88 cents a mile. Contracts differ in the base price and the miles per gallon."
          }
        },
        {
          "@type": "Question",
          "name": "Why is the published surcharge so much higher than what carriers collect?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Published tables are list prices. Large shippers negotiate their own fuel terms, the percentage applies only to part of the charge, and some freight moves under other programs. At $6.529, Old Dominion's published LTL table gives 55.8%, while LTL carriers collect about 35% of their base charges."
          }
        },
        {
          "@type": "Question",
          "name": "How much do higher diesel prices raise inflation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Through freight alone, the rise from $3.749 to $6.529 diesel could add up to 0.44 percentage points to the CPI, if the whole increase is passed along. That is a one-time step in the price level, not a new ongoing rate. It does not include what people pay at the pump."
          }
        },
        {
          "@type": "Question",
          "name": "Why is the CPI effect a range?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It depends on how stores pass along a higher freight cost. If they add it dollar for dollar, the CPI effect is about 0.31 points. If they keep their usual percentage markup, it is about 0.44 points."
          }
        },
        {
          "@type": "Question",
          "name": "Why does rail react later than trucking?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Railroads usually base the surcharge on the monthly average diesel price and bill it about two months later. Union Pacific's October 2026 surcharge, for example, is based on August's average."
          }
        },
        {
          "@type": "Question",
          "name": "Why does fuel make up a smaller share of truckload bills than it used to?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Carriers' base rates have risen. The surcharge per mile follows diesel about as it always has, but it is now added to a larger base, so it is a smaller share of the total."
          }
        },
        {
          "@type": "Question",
          "name": "Is $6.529 a record diesel price?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It is the highest weekly price in EIA's series, which began in March 1994, in dollars of the day. Adjusted for inflation it would rank differently; this page does not make that adjustment."
          }
        },
        {
          "@type": "Question",
          "name": "How often is the calculator updated?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Weekly, after EIA publishes the new diesel price. New carrier reports are added as they are filed."
          }
        }
      ]
